css:
@import url("https://fonts.googleapis.com/css2?family=Be+Vietnam+Pro:wght@400;500;600;700&display=swap");
:root{--bg:#0D1117;--panel:#161B22;--panel-2:#1F2630;--line:#2A323D;--text:#D6DCE4;--muted:#8B96A5;--head:#F3F6FA;--blue:#58A6FF;--peach:#FFB86B;--grn:#3FB950;--red:#F85149;--vio:#A78BFA;
--font:"Be Vietnam Pro",system-ui,-apple-system,"Segoe UI",sans-serif}
[data-theme="light"]{--bg:#F4F6F9;--panel:#FFFFFF;--panel-2:#F0F3F7;--line:#E1E6EC;--text:#2A3240;--muted:#6A7483;--head:#111827;--blue:#2563EB;--peach:#EA8A1F;--grn:#16A34A;--red:#DC2626;--vio:#7C3AED}
*,*::before,*::after{box-sizing:border-box}
body{margin:0;font-family:var(--font);font-size:15px;line-height:1.5;color:var(--text);background:var(--bg);-webkit-font-smoothing:antialiased;transition:background .2s,color .2s}
a{color:inherit}img{display:block;max-width:100%}h1,h2,h3{margin:0;color:var(--head);font-weight:600}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--blue);color:#fff;padding:10px;z-index:99}
:focus-visible{outline:2px solid var(--blue);outline-offset:2px;border-radius:6px}
.app{display:grid;grid-template-columns:232px 1fr;min-height:100vh}
.side{background:var(--panel);border-right:1px solid var(--line);padding:20px 12px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column}
.brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:18px;text-decoration:none;color:var(--head);padding:0 10px 20px}
.brand i{width:28px;height:28px;border-radius:50%;background:var(--blue);box-shadow:0 0 0 3px var(--panel),0 0 0 5px var(--peach)}
.nav-l{list-style:none;padding:0;margin:0}
.nav-l b{display:block;font-size:11px;letter-spacing:.08em;color:var(--muted);margin:16px 10px 6px;font-weight:600}
.nav-l a{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;text-decoration:none;color:var(--muted);font-weight:500}
.nav-l a:hover{background:var(--panel-2);color:var(--head)}.nav-l a.on{background:var(--panel-2);color:var(--head);box-shadow:inset 3px 0 0 var(--blue)}
.nav-l .n{margin-left:auto;font-size:12px;background:var(--panel-2);border:1px solid var(--line);border-radius:999px;padding:0 8px}
.env{margin-top:auto;border:1px solid var(--line);border-radius:10px;padding:12px;font-size:13px}.env b{color:var(--grn)}
.main{min-width:0}
.top{display:flex;align-items:center;gap:12px;padding:14px 24px;border-bottom:1px solid var(--line);background:var(--panel);position:sticky;top:0;z-index:10}
.menu-btn{display:none;background:none;border:1px solid var(--line);border-radius:8px;padding:6px 10px;color:var(--text);cursor:pointer}
.crumbs{color:var(--muted);font-size:14px}.crumbs b{color:var(--head);font-weight:600}
.top .r{margin-left:auto;display:flex;gap:10px;align-items:center}
.cmdk{display:flex;align-items:center;gap:8px;border:1px solid var(--line);background:var(--panel-2);border-radius:8px;padding:6px 12px;color:var(--muted);font-size:14px}
.cmdk kbd{font-family:inherit;border:1px solid var(--line);border-radius:4px;padding:0 6px;font-size:12px}
.tbtn{background:var(--panel-2);border:1px solid var(--line);color:var(--text);border-radius:8px;padding:6px 12px;font:inherit;font-size:14px;cursor:pointer}
.top img{width:32px;height:32px;border-radius:50%;object-fit:cover}
.content{padding:22px 24px 40px}
.title{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:18px;flex-wrap:wrap}
.title h1{font-size:24px}.title p{margin:2px 0 0;color:var(--muted);font-size:14px}
.btn{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border-radius:8px;font-weight:600;font-size:14px;border:1px solid var(--line);background:var(--panel-2);color:var(--head);cursor:pointer;font-family:var(--font)}
.btn.pri{background:var(--blue);border-color:var(--blue);color:#fff}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:14px}
.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px}
.kpi small{color:var(--muted)}.kpi .v{font-size:26px;font-weight:700;color:var(--head);margin:4px 0}
.kpi .d{font-size:13px;font-weight:600}.g{color:var(--grn)}.rd{color:var(--red)}
.row{display:grid;grid-template-columns:1.8fr 1fr;gap:14px;margin-bottom:14px}
.card-h{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;gap:10px;flex-wrap:wrap}
.card h2{font-size:16px}
#mrr{width:100%;height:230px}
.plans .p{margin-bottom:14px}
.stack{display:flex;height:14px;border-radius:7px;overflow:hidden;margin:6px 0 16px}
.plans .lab{display:flex;justify-content:space-between;font-size:14px;padding:6px 0;border-bottom:1px solid var(--line)}
.plans .lab i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:8px}
.health{margin-top:10px}
.svc{display:flex;justify-content:space-between;align-items:center;padding:7px 0;font-size:14px}
.svc span:last-child{font-size:13px;font-weight:600}.ok{color:var(--grn)}.warn{color:var(--peach)}
.users-h{display:flex;gap:10px;flex-wrap:wrap}
.users-h input,.users-h select{background:var(--panel-2);border:1px solid var(--line);color:var(--text);border-radius:8px;padding:8px 12px;font:inherit;font-size:14px}
.users-h input{width:220px}
.tw{overflow-x:auto}
table{width:100%;border-collapse:collapse;min-width:680px;font-size:14px}
th{text-align:left;color:var(--muted);font-weight:500;padding:10px;border-bottom:1px solid var(--line);font-size:13px}
td{padding:10px;border-bottom:1px solid var(--line)}
tr:hover td{background:var(--panel-2)}
.u{display:flex;align-items:center;gap:10px}.u img{width:30px;height:30px;border-radius:50%;object-fit:cover}.u b{display:block;color:var(--head);font-weight:600}.u small{color:var(--muted)}
.pill{font-size:12px;font-weight:600;border-radius:999px;padding:2px 9px;border:1px solid var(--line)}
.pl-Pro{color:var(--blue)}.pl-Business{color:var(--vio)}.pl-Free{color:var(--muted)}
.st-Active{color:var(--grn)}.st-Trial{color:var(--peach)}.st-Suspended{color:var(--red)}
.st::before{content:"● "}
.row3{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}
.switch{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--line);font-size:14px;gap:12px}
.switch small{display:block;color:var(--muted)}
.tg{position:relative;width:40px;height:22px;flex:none}
.tg input{opacity:0;width:0;height:0}
.tg span{position:absolute;inset:0;background:var(--line);border-radius:999px;cursor:pointer;transition:.2s}
.tg span::after{content:"";position:absolute;width:16px;height:16px;left:3px;top:3px;background:#fff;border-radius:50%;transition:.2s}
.tg input:checked+span{background:var(--blue)}.tg input:checked+span::after{transform:translateX(18px)}
.tg input:focus-visible+span{outline:2px solid var(--blue);outline-offset:2px}
.log{list-style:none;padding:0;margin:0;font-size:14px}
.log li{display:grid;grid-template-columns:70px 1fr;gap:10px;padding:8px 0;border-bottom:1px solid var(--line)}
.log time{color:var(--muted);font-size:13px}
.log code{font-size:13px;background:var(--panel-2);padding:1px 6px;border-radius:4px;color:var(--peach)}
.foot{color:var(--muted);font-size:13px;margin-top:22px;text-align:center}.foot a{color:var(--blue)}
@media (max-width:1150px){.kpis{grid-template-columns:1fr 1fr}.row,.row3{grid-template-columns:1fr}}
@media (max-width:860px){.app{grid-template-columns:1fr}.side{position:fixed;left:0;top:0;width:240px;z-index:30;transform:translateX(-100%);transition:transform .25s}.side.open{transform:none}.menu-btn{display:block}.cmdk{display:none}}
@media (max-width:520px){.kpis{grid-template-columns:1fr}.content{padding:16px 12px}.users-h input{width:100%}}

