function users(){const q=document.getElementById('q').value.toLowerCase(),fp=document.getElementById('fp').value,fs=document.getElementById('fs').value;
const rows=U.map((u,i)=>[u,i]).filter(([u])=>(!q||(u[0]+u[1]).toLowerCase().includes(q))&&(!fp||u[2]===fp)&&(!fs||u[3]===fs));
