['q','fp','fs'].forEach(id=>document.getElementById(id).addEventListener('input',users));users();
const v=[71,74,78,83,87,92,97,103,108,114,121,128],L=["Nov","Dec","Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct"];
function chart(){const s=document.getElementById('mrr'),W=s.clientWidth||700,H=230,pl=40,pb=24,mn=60,mx=135,cs=getComputedStyle(document.documentElement),blue=cs.getPropertyValue('--blue').trim(),line=cs.getPropertyValue('--line').trim(),mut=cs.getPropertyValue('--muted').trim();
const X=i=>pl+i/(v.length-1)*(W-pl-10),Y=x=>H-pb-(x-mn)/(mx-mn)*(H-pb-10);let g=`<defs><linearGradient id="ga" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="${blue}" stop-opacity=".35"/><stop offset="1" stop-color="${blue}" stop-opacity="0"/></linearGradient></defs>`;
for(let j=0;j<=3;j++){const val=mn+(mx-mn)*j/3,y=Y(val);g+=`<line x1="${pl}" x2="${W-10}" y1="${y}" y2="${y}" stroke="${line}"/><text x="${pl-6}" y="${y+4}" text-anchor="end" font-size="11" fill="${mut}">$${Math.round(val)}k</text>`}
const d=v.map((x,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(x).toFixed(1)).join(' ');
g+=`<path d="${d} L${X(v.length-1)} ${H-pb} L${pl} ${H-pb}Z" fill="url(#ga)"/><path d="${d}" fill="none" stroke="${blue}" stroke-width="2.5"/>`;
v.forEach((x,i)=>{if(i%2===1)g+=`<text x="${X(i)}" y="${H-6}" text-anchor="middle" font-size="11" fill="${mut}">${L[i]}</text>`});
g+=`<circle cx="${X(11)}" cy="${Y(128)}" r="5" fill="${blue}"/>`;s.setAttribute('viewBox',`0 0 ${W} ${H}`);s.innerHTML=g}
chart();window.addEventListener('resize',chart);
const tb=document.getElementById('theme');tb.addEventListener('click',()=>{const l=document.documentElement.dataset.theme==='light';document.documentElement.dataset.theme=l?'dark':'light';tb.textContent=l?'☀ Light mode':'☾ Dark mode';tb.setAttribute('aria-pressed',!l);chart()});
